SELECT DISTINCT ('NaN'::text || LEFT ('a'::text, 1)) AS c0, (SELECT COUNT (((a3.c0 % 100) * (NULLIF (2, (-5)) % 100))) FROM JSON_TABLE ('{"k": 0, "a": [3, 4, 5]}'::jsonb, '$[*]' COLUMNS (c0 int PATH '$.k', c1 text PATH '$')) AS a3) AS c1 FROM t0 AS a1, JSON_TABLE (JSONB_BUILD_OBJECT ('k', CASE WHEN (ROW ('-1 month'::interval, '2000-01-01'::date) >= ROW ('00:00:00.000001'::interval, '1970-01-01'::date)) THEN CASE ('abc'::text LIKE '%\\%'::text) WHEN FALSE THEN 'abc'::text WHEN (('{"k": -1, "a": [1, 2, 3]}'::jsonb @@ '$.a[*] > 1') OR FALSE) THEN UPPER ('abc'::text) ELSE ('ß'::text || 'x%'::text) END ELSE (42.5::numeric)::text END), '$[*]' COLUMNS (c0 int PATH '$.k', c1 text PATH '$')) AS a2;
